14	export interface IngestOptions {
15	  /** Directory containing raw .json news files. Defaults to "data/raw". */
16	  dataDir?: string;
17	  /** Date string (YYYY-MM-DD) for the ingest summary. Defaults to today. */
18	  date?: string;
19	}
20	
21	/**
22	 * Execute the complete INGEST pipeline:
23	 *
24	 * 1. Read all .json files from the data directory (NewsReader)
25	 * 2. Validate, deduplicate, and compile statistics (NewsValidator)
26	 * 3. Return the validation result with summary
27	 *
28	 * Progress is logged at each stage using the "INGEST" logger module.
29	 *
30	 * @param options - Optional pipeline configuration.
31	 * @returns A ValidationResult containing valid items, skipped items, and summary.
32	 */
33	export async function runIngest(options?: IngestOptions): Promise<ValidationResult> {
34	  const logger = new Logger('INGEST');
35	
36	  logger.info('Starting INGEST pipeline');
37	
38	  // ── Phase 1: Read ─────────────────────────────────────────────────────
39	  logger.info('Phase 1: Reading news files', options?.dataDir ? { dataDir: options.dataDir } : undefined);
40	  const reader = new NewsReader({ dataDir: options?.dataDir });
41	  const items = await reader.loadAll();
42	  logger.info(`Phase 1 complete: Loaded ${items.length} raw item(s) from reader`);
43	
44	  // ── Phase 2: Validate ─────────────────────────────────────────────────
45	  logger.info('Phase 2: Validating and cleaning data');
46	  const validator = new NewsValidator({ date: options?.date });
47	  const result = validator.validate(items);
48	
49	  // ── Phase 3: Summary ──────────────────────────────────────────────────
50	  logger.info(
51	    `Phase 2 complete: ${result.summary.validated} valid, ${result.summary.skipped} skipped (of ${result.summary.total_input} total)`,
52	  );
53	
54	  logger.info('INGEST pipeline finished successfully');
55	
56	  return result;
57	}
58

