1	import Anthropic from '@anthropic-ai/sdk';
2	import type { Message, MessageCreateParamsNonStreaming } from '@anthropic-ai/sdk/resources/messages/messages.js';
3	
4	// ---------------------------------------------------------------------------
5	// Public types
6	// ---------------------------------------------------------------------------
7	
8	export interface LLMOptions {
9	  model?: string;
10	  maxTokens?: number;
11	  temperature?: number;
12	  timeout?: number;
13	}
14	
15	export interface LLMResponse {
16	  content: string;
17	  model: string;
18	  usage: {
19	    inputTokens: number;
20	    outputTokens: number;
21	  };
22	  durationMs: number;
23	}
24	
25	export interface LLMClientConfig {
26	  maxRetries?: number;   // default 3
27	  baseDelayMs?: number;  // default 1000
28	  apiKey?: string;       // default process.env.ANTHROPIC_API_KEY
29	}
30	
31	// ---------------------------------------------------------------------------
32	// Client
33	// ---------------------------------------------------------------------------
34	
35	const DEFAULT_MODEL = 'claude-sonnet-4-20250514';
36	const DEFAULT_MAX_TOKENS = 1024;
37	
38	export class LLMClient {
39	  private readonly anthropic: Anthropic;
40	  private readonly maxRetries: number;
41	  private readonly baseDelayMs: number;
42	
43	  /**
44	   * @param config         Public config options.
45	   * @param config.anthropic  Optional pre-configured Anthropic SDK instance
46	   *                          (used for dependency injection / testing).
47	   */
48	  constructor(
49	    config?: LLMClientConfig & { anthropic?: Anthropic },
50	  ) {
51	    this.maxRetries = config?.maxRetries ?? 3;
52	    this.baseDelayMs = config?.baseDelayMs ?? 1000;
53	
54	    if (config?.anthropic) {
55	      this.anthropic = config.anthropic;
56	    } else {
57	      this.anthropic = new Anthropic({
58	        apiKey: config?.apiKey ?? process.env.ANTHROPIC_API_KEY,
59	      });
60	    }
61	  }
62	
63	  // -----------------------------------------------------------------------
64	  // Public API
65	  // -----------------------------------------------------------------------
66	
67	  /**
68	   * Send a prompt to the LLM and receive a structured response.
69	   * Automatically retries on retry-able errors (network timeout, 429, 5xx).
70	   */
71	  async send(prompt: string, options?: LLMOptions): Promise<LLMResponse> {
72	    const startTime = Date.now();
73	
74	    for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
75	      try {
76	        const body: MessageCreateParamsNonStreaming = {
77	          model: options?.model ?? DEFAULT_MODEL,
78	          max_tokens: options?.maxTokens ?? DEFAULT_MAX_TOKENS,
79	          messages: [{ role: 'user', content: prompt }],
80	          ...(options?.temperature !== undefined ? { temperature: options.temperature } : {}),
81	        };
82	
83	        const response = await this.anthropic.messages.create(body, {
84	          timeout: options?.timeout,
85	        });
86	
87	        const durationMs = Date.now() - startTime;
88	        const content = (response.content as Array<{ type: string; text?: string }>)
89	          .filter((b) => b.type === 'text')
90	          .map((b) => b.text ?? '')
91	          .join('');
92	
93	        return {
94	          content,
95	          model: response.model,
96	          usage: {
97	            inputTokens: response.usage.input_tokens,
98	            outputTokens: response.usage.output_tokens,
99	          },
100	          durationMs,
101	        };
102	      } catch (err: unknown) {
103	        // If this is the last attempt, rethrow immediately.
104	        if (attempt >= this.maxRetries || !this.isRetryable(err)) {
105	          throw err;
106	        }
107	
108	        const delayMs = this.baseDelayMs * Math.pow(2, attempt);
109	        console.log(
110	          `[WARN] LLM call failed (attempt ${attempt + 1}/${this.maxRetries + 1}), retrying in ${delayMs}ms: ${(err as Error).message}`,
111	        );
112	        await this.sleep(delayMs);
113	      }
114	    }
115	
116	    // Unreachable -- the loop always returns or throws.
117	    throw new Error('Unexpected state in LLMClient.send');
118	  }
119	
120	  // -----------------------------------------------------------------------
121	  // Static factory
122	  // -----------------------------------------------------------------------
123	
124	  /**
125	   * Create a mock LLMClient that does **not** make real API calls.
126	   *
127	   * @param stubResponse  Return this LLMResponse on success, or throw this
128	   *                      Error on failure.  The full retry machinery is still
129	   *                      active so you can test retry exhaustion.
130	   */
131	  static createMock(stubResponse: LLMResponse | Error): LLMClient {
132	    const mockAnthropic = {
133	      messages: {
134	        create: async (): Promise<Message> => {
135	          if (stubResponse instanceof Error) {
136	            throw stubResponse;
137	          }
138	          return {
139	            id: 'mock_msg_id',
140	            type: 'message',
141	            role: 'assistant',
142	            content: [{ type: 'text', text: stubResponse.content }],
143	            model: stubResponse.model,
144	            usage: {
145	              input_tokens: stubResponse.usage.inputTokens,
146	              output_tokens: stubResponse.usage.outputTokens,
147	            },
148	          } as Message;
149	        },
150	      },
151	    };
152	
153	    return new LLMClient({ anthropic: mockAnthropic as unknown as Anthropic });
154	  }
155	
156	  // -----------------------------------------------------------------------
157	  // Private helpers
158	  // -----------------------------------------------------------------------
159	
160	  /**
161	   * Determine whether an error is worth retrying.
162	   *
163	   * Retry-able:
164	   *   - Network / connection errors  (status === undefined)
165	   *   - HTTP 429 (rate-limit)
166	   *   - HTTP 5xx (server errors)
167	   *
168	   * Non-retry-able (thrown immediately):
169	   *   - HTTP 401 (auth)
170	   *   - HTTP 403 (permission)
171	   *   - HTTP 400 (bad request)
172	   */
173	  private isRetryable(err: unknown): boolean {
174	    const error = err as { status?: number };
175	    const status = error.status;
176	
177	    // Non-retry-able status codes
178	    if (status === 401 || status === 403 || status === 400) {
179	      return false;
180	    }
181	
182	    // Retry-able: rate limits, server errors, network timeouts
183	    if (status === 429) return true;
184	    if (status !== undefined && status >= 500) return true;
185	    if (status === undefined) return true; // e.g. APIConnectionTimeoutError
186	
187	    return false;
188	  }
189	
190	  /** Promise-based delay for retry back-off. */
191	  private sleep(ms: number): Promise<void> {
192	    return new Promise((resolve) => setTimeout(resolve, ms));
193	  }
194	}
195

1	/**
2	 * Logger — 分级日志工具
3	 *
4	 * Provides 5 log levels (DEBUG, INFO, WARN, ERROR, FATAL) with
5	 * global level control, stdout/stderr routing, and structured data support.
6	 */
7	
8	/**
9	 * Log levels ordered by severity (lower number = more verbose).
10	 */
11	export enum LogLevel {
12	  DEBUG = 0,
13	  INFO = 1,
14	  WARN = 2,
15	  ERROR = 3,
16	  FATAL = 4,
17	}
18	
19	/**
20	 * Represents a single structured log entry.
21	 */
22	export interface LogEntry {
23	  timestamp: string;
24	  level: LogLevel;
25	  module: string;
26	  message: string;
27	  data?: Record<string, unknown>;
28	}
29	
30	/**
31	 * Optional configuration for Logger constructor.
32	 */
33	export interface LoggerOptions {
34	  // Reserved for future options (e.g., custom output stream, formatting)
35	}
36	
37	/**
38	 * Mapping from LogLevel enum to display name strings.
39	 */
40	const LEVEL_NAMES: Record<LogLevel, string> = {
41	  [LogLevel.DEBUG]: 'DEBUG',
42	  [LogLevel.INFO]: 'INFO',
43	  [LogLevel.WARN]: 'WARN',
44	  [LogLevel.ERROR]: 'ERROR',
45	  [LogLevel.FATAL]: 'FATAL',
46	};
47	
48	/**
49	 * Parse a log level string from environment variable or config.
50	 * Returns null for invalid / unrecognized values.
51	 */
52	function parseLogLevel(value: string | undefined): LogLevel | null {
53	  if (!value) return null;
54	  const upper = value.toUpperCase().trim();
55	  for (const [key, val] of Object.entries(LogLevel)) {
56	    if (typeof val === 'number' && key === upper) {
57	      return val as LogLevel;
58	    }
59	  }
60	  return null;
61	}
62	
63	/**
64	 * Current global log level. All log entries below this threshold are suppressed.
65	 * Initialized from the LOG_LEVEL environment variable, defaulting to INFO.
66	 */
67	let globalLevel: LogLevel =
68	  parseLogLevel(
69	    typeof process !== 'undefined' ? process.env.LOG_LEVEL : undefined,
70	  ) ?? LogLevel.INFO;
71	
72	/**
73	 * Generate an ISO 8601 timestamp (UTC).
74	 */
75	function formatTimestamp(): string {
76	  return new Date().toISOString();
77	}
78	
79	/**
80	 * Logger — a lightweight structured logger with global level control.
81	 *
82	 * @example
83	 *   const log = new Logger('INGEST');
84	 *   log.info('Document received', { docId: 42 });
85	 *   log.error('Processing failed', { error: err.message });
86	 */
87	export class Logger {
88	  private readonly moduleName: string;
89	
90	  /**
91	   * Create a new Logger instance bound to the given module name.
92	   *
93	   * @param module  Module identifier (e.g. "INGEST", "EXTRACT", "PIPELINE")
94	   * @param _options  Optional logger configuration (reserved)
95	   */
96	  constructor(module: string, _options?: LoggerOptions) {
97	    this.moduleName = module;
98	  }
99	
100	  // ─── Instance methods ────────────────────────────────────────
101	
102	  /** Log a DEBUG message (lowest severity). */
103	  debug(message: string, data?: Record<string, unknown>): void {
104	    this.log(LogLevel.DEBUG, message, data);
105	  }
106	
107	  /** Log an INFO message. */
108	  info(message: string, data?: Record<string, unknown>): void {
109	    this.log(LogLevel.INFO, message, data);
110	  }
111	
112	  /** Log a WARN message. */
113	  warn(message: string, data?: Record<string, unknown>): void {
114	    this.log(LogLevel.WARN, message, data);
115	  }
116	
117	  /** Log an ERROR message (routed to stderr). */
118	  error(message: string, data?: Record<string, unknown>): void {
119	    this.log(LogLevel.ERROR, message, data);
120	  }
121	
122	  /** Log a FATAL message (routed to stderr, highest severity). */
123	  fatal(message: string, data?: Record<string, unknown>): void {
124	    this.log(LogLevel.FATAL, message, data);
125	  }
126	
127	  // ─── Static methods ──────────────────────────────────────────
128	
129	  /**
130	   * Override the global log level at runtime.
131	   * All loggers share this threshold.
132	   */
133	  static setGlobalLevel(level: LogLevel): void {
134	    globalLevel = level;
135	  }
136	
137	  /**
138	   * Read the current global log level.
139	   */
140	  static getGlobalLevel(): LogLevel {
141	    return globalLevel;
142	  }
143	
144	  // ─── Private helpers ─────────────────────────────────────────
145	
146	  /**
147	   * Core log method: filters by global level, formats the message,
148	   * and writes to stdout or stderr.
149	   */
150	  private log(level: LogLevel, message: string, data?: Record<string, unknown>): void {
151	    // Skip messages below the global threshold
152	    if (level < globalLevel) {
153	      return;
154	    }
155	
156	    const timestamp = formatTimestamp();
157	    const levelName = LEVEL_NAMES[level];
158	    let output = `[${timestamp}] [${levelName}] [${this.moduleName}] ${message}`;
159	
160	    // Append structured data as JSON when provided
161	    if (data !== undefined) {
162	      output += ` ${JSON.stringify(data)}`;
163	    }
164	
165	    output += '\n';
166	
167	    // Route ERROR and FATAL to stderr, everything else to stdout
168	    if (level >= LogLevel.ERROR) {
169	      process.stderr.write(output);
170	    } else {
171	      process.stdout.write(output);
172	    }
173	  }
174	}
