1	// =============================================================================
2	// M2 EXTRACT — 批量结构化抽取编排器
3	// =============================================================================
4	
5	import { LLMClient, LLMOptions, LLMResponse } from '../llm-client.js';
6	import { Logger } from '../logger.js';
7	import {
8	  RawNewsItem,
9	  StructuredInsightItem,
10	  ExtractionSummary,
11	} from '../schema/types.js';
12	import { StructuredInsightItemSchema } from '../schema/schemas.js';
13	import { buildExtractionPrompt, buildRemedialPrompt } from './prompt-builder.js';
14	
15	// ---------------------------------------------------------------------------
16	// Public types
17	// ---------------------------------------------------------------------------
18	
19	export interface ExtractorOptions {
20	  /** LLM 客户端实例（依赖注入） */
21	  llmClient: LLMClient;
22	  /** 最大并发数，默认 3 */
23	  maxParallel?: number;
24	  /** 补救重试次数（默认 1，即尝试一次补救） */
25	  maxRetries?: number;
26	  /** 最小置信度阈值，低于此触发补救重试，默认 0.4 */
27	  minConfidence?: number;
28	  /** 低于此置信度标记 needs_review，默认 0.6 */
29	  minConfidenceForReview?: number;
30	  /** 传给 LLMClient.send 的额外选项 */
31	  llmOptions?: LLMOptions;
32	}
33	
34	// ---------------------------------------------------------------------------
35	// Constants
36	// ---------------------------------------------------------------------------
37	
38	const DEFAULT_MAX_PARALLEL = 3;
39	const DEFAULT_MAX_RETRIES = 1;
40	const DEFAULT_MIN_CONFIDENCE = 0.4;
41	const DEFAULT_MIN_CONFIDENCE_FOR_REVIEW = 0.6;
42	
43	// ---------------------------------------------------------------------------
44	// NewsExtractor
45	// ---------------------------------------------------------------------------
46	
47	export class NewsExtractor {
48	  private readonly logger: Logger;
49	
50	  constructor(private readonly options: ExtractorOptions) {
51	    this.logger = new Logger('EXTRACT');
52	  }
53	
54	  // ── Private option accessors ──────────────────────────────────────────
55	
56	  private get maxParallel(): number {
57	    return this.options.maxParallel ?? DEFAULT_MAX_PARALLEL;
58	  }
59	
60	  private get maxRetries(): number {
61	    return this.options.maxRetries ?? DEFAULT_MAX_RETRIES;
62	  }
63	
64	  private get minConfidence(): number {
65	    return this.options.minConfidence ?? DEFAULT_MIN_CONFIDENCE;
66	  }
67	
68	  private get minConfidenceForReview(): number {
69	    return this.options.minConfidenceForReview ?? DEFAULT_MIN_CONFIDENCE_FOR_REVIEW;
70	  }
71	
72	  // ── Public API ────────────────────────────────────────────────────────
73	
74	  /**
75	   * 逐条处理 RawNewsItem[]，返回结构化结果及统计摘要。
76	   *
77	   * 使用简单的批次并发控制：每批最多 maxParallel 条，通过 Promise.all 并行处理。
78	   */
79	  async extractBatch(items: RawNewsItem[]): Promise<{
80	    items: StructuredInsightItem[];
81	    summary: ExtractionSummary;
82	  }> {
83	    const startTime = Date.now();
84	
85	    this.logger.info(`Starting EXTRACT batch: ${items.length} item(s)`);
86	
87	    if (items.length === 0) {
88	      return {
89	        items: [],
90	        summary: this.buildSummary([], startTime),
91	      };
92	    }
93	
94	    const allResults: (StructuredInsightItem | null)[] = [];
95	
96	    // Batch-based concurrency control
97	    for (let i = 0; i < items.length; i += this.maxParallel) {
98	      const batch = items.slice(i, i + this.maxParallel);
99	      this.logger.info(
100	        `Processing batch ${Math.floor(i / this.maxParallel) + 1}/${Math.ceil(items.length / this.maxParallel)} (${batch.length} item(s))`,
101	      );
102	
103	      const batchResults = await Promise.all(
104	        batch.map((item) => this.extractOne(item)),
105	      );
106	
107	      allResults.push(...batchResults);
108	    }
109	
110	    const successful = allResults.filter(
111	      (r): r is StructuredInsightItem => r !== null,
112	    );
113	
114	    this.logger.info(
115	      `EXTRACT batch complete: ${successful.length}/${items.length} extracted successfully`,
116	    );
117	
118	    return {
119	      items: successful,
120	      summary: this.buildSummary(allResults, startTime),
121	    };
122	  }
123	
124	  // ── Private: 单条抽取 ────────────────────────────────────────────────
125	
126	  /**
127	   * 处理单条新闻：抽取 + 校验 + 可能的补救重试。
128	   * 返回 StructuredInsightItem 或 null（失败时）。
129	   */
130	  private async extractOne(
131	    item: RawNewsItem,
132	  ): Promise<StructuredInsightItem | null> {
133	    const llmOptions = this.options.llmOptions;
134	
135	    // ── First attempt ────────────────────────────────────────────────
136	    const prompt = buildExtractionPrompt(item);
137	    const response = await this.options.llmClient.send(prompt, llmOptions);
138	    const result = this.tryParseAndValidate(response.content);
139	
140	    if (result) {
141	      // Check if confidence meets the threshold
142	      if (result.extraction_confidence >= this.minConfidence) {
143	        this.setReviewFlags(result);
144	        return result;
145	      }
146	    }
147	
148	    // ── Remedial attempt ─────────────────────────────────────────────
149	    if (this.maxRetries > 0) {
150	      const prevConfidence = result?.extraction_confidence ?? 0;
151	      const reason = result
152	        ? `low extraction confidence (${prevConfidence})`
153	        : 'schema validation failed';
154	
155	      this.logger.info(
156	        `Remedial retry for ${item.id}: confidence=${prevConfidence}, reason=${reason}`,
157	      );
158	
159	      const remedialPrompt = buildRemedialPrompt(
160	        item,
161	        prevConfidence,
162	        reason,
163	      );
164	      const remedialResponse = await this.options.llmClient.send(
165	        remedialPrompt,
166	        llmOptions,
167	      );
168	      const remedialResult = this.tryParseAndValidate(
169	        remedialResponse.content,
170	      );
171	
172	      if (remedialResult) {
173	        if (remedialResult.extraction_confidence >= this.minConfidence) {
174	          this.setReviewFlags(remedialResult);
175	          return remedialResult;
176	        }
177	      }
178	
179	      this.logger.error(
180	        `Remedial extraction failed for ${item.id}`,
181	        remedialResult
182	          ? { confidence: remedialResult.extraction_confidence }
183	          : { reason: 'parse or validation failed' },
184	      );
185	    }
186	
187	    this.logger.error(
188	      `Extraction failed for ${item.id}`,
189	      result
190	        ? { confidence: result.extraction_confidence }
191	        : { reason: 'initial parse or validation failed' },
192	    );
193	
194	    return null;
195	  }
196	
197	  // ── Private: 解析与校验 ──────────────────────────────────────────────
198	
199	  /**
200	   * 尝试解析 LLM 返回的 JSON 并进行 Zod 校验。
201	   * 返回解析并校验通过的对象，或 null。
202	   */
203	  private tryParseAndValidate(
204	    responseText: string,
205	  ): StructuredInsightItem | null {
206	    let parsed: unknown;
207	    try {
208	      const cleaned = this.cleanJsonResponse(responseText);
209	      parsed = JSON.parse(cleaned);
210	    } catch {
211	      return null;
212	    }
213	
214	    const parsedResult = StructuredInsightItemSchema.safeParse(parsed);
215	    if (!parsedResult.success) {
216	      return null;
217	    }
218	
219	    return parsedResult.data;
220	  }
221	
222	  /**
223	   * 清理 LLM 输出中的 Markdown 代码块标记，返回纯 JSON 字符串。
224	   */
225	  private cleanJsonResponse(text: string): string {
226	    let cleaned = text.trim();
227	
228	    // Remove leading ```json or ``` markers
229	    if (cleaned.startsWith('```json')) {
230	      cleaned = cleaned.slice(7);
231	    } else if (cleaned.startsWith('```')) {
232	      cleaned = cleaned.slice(3);
233	    }
234	
235	    // Remove trailing ``` markers
236	    if (cleaned.endsWith('```')) {
237	      cleaned = cleaned.slice(0, -3);
238	    }
239	
240	    return cleaned.trim();
241	  }
242	
243	  // ── Private: 审核标记 ────────────────────────────────────────────────
244	
245	  /**
246	   * 根据 extraction_confidence 设置 needs_review 和 review_reason。
247	   */
248	  private setReviewFlags(item: StructuredInsightItem): void {
249	    item.needs_review =
250	      item.extraction_confidence < this.minConfidenceForReview;
251	    if (item.needs_review && !item.review_reason) {
252	      item.review_reason = `low extraction confidence (${item.extraction_confidence})`;
253	    }
254	  }
255	
256	  // ── Private: 统计摘要 ────────────────────────────────────────────────
257	
258	  /**
259	   * 根据所有抽取结果构建 ExtractionSummary。
260	   */
261	  private buildSummary(
262	    results: (StructuredInsightItem | null)[],
263	    startTime: number,
264	  ): ExtractionSummary {
265	    const successful = results.filter(
266	      (r): r is StructuredInsightItem => r !== null,
267	    );
268	    const needsReview = successful.filter((r) => r.needs_review);
269	    const totalItems = results.length;
270	    const skipped = results.filter((r) => r === null).length;
271	
272	    const avgConfidence =
273	      successful.length > 0
274	        ? successful.reduce((sum, r) => sum + r.extraction_confidence, 0) /
275	          successful.length
276	        : 0;
277	
278	    return {
279	      date: new Date().toISOString().slice(0, 10),
280	      total_items: totalItems,
281	      extracted_successfully: successful.length,
282	      needs_review: needsReview.length,
283	      skipped,
284	      average_confidence: avgConfidence,
285	      extraction_duration_seconds: (Date.now() - startTime) / 1000,
286	    };
287	  }
288	}
289

1	// =============================================================================
2	// M3 SYNTHESIZE — StatsAggregator: 纯统计聚合（无 AI）
3	// =============================================================================
4	
5	import { StructuredInsightItem, AggregationStats } from '../schema/types.js';
6	
7	/**
8	 * StatsAggregator — 对结构化洞察数据进行统计聚合
9	 *
10	 * 所有计算均为纯 TypeScript，禁止调用任何 AI/LLM。
11	 */
12	export class StatsAggregator {
13	  /**
14	   * 单次调用: 对所有结构化数据进行统计聚合
15	   */
16	  aggregate(items: StructuredInsightItem[]): AggregationStats {
17	    return {
18	      topic_frequency: this.countTopics(items),
19	      source_distribution: this.countSources(items),
20	      sentiment_distribution: this.countSentiments(items),
21	      risk_distribution: this.countRisks(items),
22	      top_by_significance: this.topByScore(items),
23	      entity_co_occurrence: this.coOccurrence(items),
24	    };
25	  }
26	
27	  // ===========================================================================
28	  // Private helpers
29	  // ===========================================================================
30	
31	  /**
32	   * 话题频次 — 遍历 items 中所有 topics，按 label 聚合计数
33	   */
34	  private countTopics(items: StructuredInsightItem[]): Record<string, number> {
35	    const freq: Record<string, number> = {};
36	    for (const item of items) {
37	      for (const topic of item.topics) {
38	        const label = topic.label;
39	        freq[label] = (freq[label] ?? 0) + 1;
40	      }
41	    }
42	    return freq;
43	  }
44	
45	  /**
46	   * 来源分布 — 按 source.type 聚合
47	   */
48	  private countSources(items: StructuredInsightItem[]): Record<string, number> {
49	    const dist: Record<string, number> = {};
50	    for (const item of items) {
51	      const type = item.source.type;
52	      dist[type] = (dist[type] ?? 0) + 1;
53	    }
54	    return dist;
55	  }
56	
57	  /**
58	   * 情感分布 — 按 sentiment.overall 聚合
59	   */
60	  private countSentiments(items: StructuredInsightItem[]): Record<string, number> {
61	    const dist: Record<string, number> = {};
62	    for (const item of items) {
63	      const overall = item.sentiment.overall;
64	      dist[overall] = (dist[overall] ?? 0) + 1;
65	    }
66	    return dist;
67	  }
68	
69	  /**
70	   * 风险分布 — 按 risk_level 聚合
71	   */
72	  private countRisks(items: StructuredInsightItem[]): Record<string, number> {
73	    const dist: Record<string, number> = {};
74	    for (const item of items) {
75	      const level = item.risk_level;
76	      dist[level] = (dist[level] ?? 0) + 1;
77	    }
78	    return dist;
79	  }
80	
81	  /**
82	   * 显著性 Top-10 — 按 impact.significance_score 降序排列，取前 10
83	   */
84	  private topByScore(
85	    items: StructuredInsightItem[],
86	  ): Array<{ id: string; title: string; score: number; published_at: string }> {
87	    return items
88	      .slice()
89	      .sort((a, b) => b.impact.significance_score - a.impact.significance_score)
90	      .slice(0, 10)
91	      .map((item) => ({
92	        id: item.id,
93	        title: item.title,
94	        score: item.impact.significance_score,
95	        published_at: item.ingested_at,
96	      }));
97	  }
98	
99	  /**
100	   * 实体共现 — 基于 entities.companies，构建共现对（同一 news 中出现的两两配对）
101	   * weight 为共同出现次数。对按 source-target 字母序排列。
102	   */
103	  private coOccurrence(
104	    items: StructuredInsightItem[],
105	  ): Array<{ source: string; target: string; weight: number }> {
106	    const pairMap = new Map<string, number>();
107	
108	    for (const item of items) {
109	      const companies = item.entities.companies.map((c) => c.name).sort();
110	      // 只有 >= 2 个公司时才会产生共现对
111	      for (let i = 0; i < companies.length; i++) {
112	        for (let j = i + 1; j < companies.length; j++) {
113	          const key = `${companies[i]}||${companies[j]}`;
114	          pairMap.set(key, (pairMap.get(key) ?? 0) + 1);
115	        }
116	      }
117	    }
118	
119	    // 转成输出格式，按字母序排列
120	    const result = Array.from(pairMap.entries())
121	      .map(([key, weight]) => {
122	        const [source, target] = key.split('||');
123	        return { source, target, weight };
124	      })
125	      .sort((a, b) => {
126	        if (a.source !== b.source) return a.source.localeCompare(b.source);
127	        return a.target.localeCompare(b.target);
128	      });
129	
130	    return result;
131	  }
132	}
