389	  private getTopTopics(topicFrequency: Record<string, number>): string[] {
390	    return Object.entries(topicFrequency)
391	      .sort(([, a], [, b]) => b - a)
392	      .map(([label]) => label);
393	  }
394	
395	  /**
396	   * 获取风险等级标签
397	   */
398	  private getRiskLevelLabel(level: string): string {
399	    const labels: Record<string, string> = {
400	      critical: '严重',
401	      high: '高',
402	      medium: '中',
403	    };
404	    return labels[level] ?? level;
