1	import { RawNewsItem, IngestSummary, SkippedItem } from '../schema/types.js';
2	import { RawNewsItemSchema } from '../schema/schemas.js';
3	
4	// =============================================================================
5	// M1 Ingest — Data Validator
6	// =============================================================================
7	
8	export interface ValidationOptions {
9	  /** Current date for the summary, defaults to today's date (YYYY-MM-DD). */
10	  date?: string;
11	  /**
12	   * Minimum content length in characters. Items with content shorter than this
13	   * are skipped with reason "content too short". Defaults to 50, matching the
14	   * schema's built-in minimum.
15	   */
16	  minContentLength?: number;
17	}
18	
19	export interface ValidationResult {
20	  /** Items that passed all validation checks. */
21	  valid: RawNewsItem[];
22	  /** Items that were skipped, along with their skip reasons. */
23	  skipped: SkippedItem[];
24	  /** Aggregate summary of the validation run. */
25	  summary: IngestSummary;
26	}
27	
28	/**
29	 * NewsValidator — validates, cleans, and deduplicates RawNewsItem[] data.
30	 *
31	 * Validation pipeline for each item:
32	 * 1. Schema validation via RawNewsItemSchema.safeParse()
33	 * 2. Content length check against minContentLength
34	 * 3. Duplicate ID detection
35	 *
36	 * Items that fail any check are added to the `skipped` list with a reason.
37	 */
38	export class NewsValidator {
39	  private options: Required<ValidationOptions>;
40	
41	  constructor(options?: ValidationOptions) {
42	    this.options = {
43	      date: options?.date ?? todayStr(),
44	      minContentLength: options?.minContentLength ?? 50,
45	    };
46	  }
47	
48	  /**
49	   * Validate a batch of RawNewsItem objects.
50	   *
51	   * @param items - The raw items to validate.
52	   * @returns A ValidationResult containing the valid items, skipped items,
53	   *          and an aggregate summary.
54	   */
55	  validate(items: RawNewsItem[]): ValidationResult {
56	    const seenIds = new Set<string>();
57	    const valid: RawNewsItem[] = [];
58	    const skipped: SkippedItem[] = [];
59	    const sourceDist: Record<string, number> = {};
60	    const minContentLength = this.options.minContentLength;
61	
62	    for (const item of items) {
63	      // ── Step 1: Schema validation ────────────────────────────────────
64	      const parseResult = RawNewsItemSchema.safeParse(item);
65	      if (!parseResult.success) {
66	        const reason = formatZodErrors(parseResult.error);
67	        skipped.push({ id: item.id ?? '(missing)', reason });
68	        continue;
69	      }
70	
71	      // ── Step 2: Content length check ─────────────────────────────────
72	      // This catches items that pass the schema's built-in min(50) but fail
73	      // a stricter (configurable) threshold.
74	      if (item.content.length < minContentLength) {
75	        skipped.push({ id: item.id, reason: 'content too short' });
76	        continue;
77	      }
78	
79	      // ── Step 3: Duplicate ID detection ───────────────────────────────
80	      if (seenIds.has(item.id)) {
81	        skipped.push({ id: item.id, reason: 'duplicate id' });
82	        continue;
83	      }
84	
85	      // ── All checks passed ────────────────────────────────────────────
86	      seenIds.add(item.id);
87	      valid.push(item);
88	
89	      // Track source distribution
90	      const sourceType = item.source.type;
91	      sourceDist[sourceType] = (sourceDist[sourceType] ?? 0) + 1;
92	    }
93	
94	    const summary: IngestSummary = {
95	      date: this.options.date,
96	      total_input: items.length,
97	      validated: valid.length,
98	      skipped: skipped.length,
99	      skipped_reasons: skipped,
100	      source_distribution: sourceDist,
101	    };
102	
103	    return { valid, skipped, summary };
104	  }
105	}
106	
107	// ─── Helpers ─────────────────────────────────────────────────────────────────
108	
109	/**
110	 * Get today's date as YYYY-MM-DD.
111	 */
112	function todayStr(): string {
113	  return new Date().toISOString().split('T')[0];
114	}
115	
116	/**
117	 * Format Zod validation errors into a human-readable string.
118	 *
119	 * Example output: "title: Title must not be empty; content: Content must be at least 50 characters long"
120	 */
121	function formatZodErrors(error: { issues: Array<{ path: (string | number | symbol)[]; message: string }> }): string {
122	  return error.issues
123	    .map((e) => {
124	      const pathStr = e.path.length > 0 ? e.path.map(String).join('.') : '(root)';
125	      return `${pathStr}: ${e.message}`;
126	    })
127	    .join('; ');
128	}
