1	import fs from 'fs';
2	import path from 'path';
3	import { Logger } from '../logger.js';
4	import { RawNewsItem } from '../schema/types.js';
5	
6	// =============================================================================
7	// M1 Ingest — File Reader
8	// =============================================================================
9	
10	export interface ReaderOptions {
11	  /** Directory containing raw .json news files. Defaults to "data/raw". */
12	  dataDir?: string;
13	}
14	
15	/**
16	 * Resolve the default data directory relative to the current working directory.
17	 */
18	function defaultDataDir(): string {
19	  return path.resolve(process.cwd(), 'data', 'raw');
20	}
21	
22	/**
23	 * NewsReader — scans a directory for .json files and loads them as RawNewsItem[].
24	 *
25	 * Each file should contain either an array of RawNewsItem objects or a single
26	 * RawNewsItem object (which is automatically wrapped into an array).
27	 * Files that cannot be parsed or read are skipped with a WARN log.
28	 */
29	export class NewsReader {
30	  private dataDir: string;
31	  private _files: string[];
32	  private logger: Logger;
33	
34	  constructor(options?: ReaderOptions) {
35	    this.dataDir = options?.dataDir ?? defaultDataDir();
36	    this._files = [];
37	    this.logger = new Logger('INGEST');
38	  }
39	
40	  /**
41	   * Scan the configured directory and return all matching .json file paths.
42	   * Returns an empty array if the directory does not exist or cannot be read.
43	   */
44	  listFiles(): string[] {
45	    try {
46	      if (!fs.existsSync(this.dataDir)) {
47	        this.logger.warn(`Data directory does not exist: ${this.dataDir}`);
48	        this._files = [];
49	        return [];
50	      }
51	
52	      const entries = fs.readdirSync(this.dataDir);
53	      this._files = entries
54	        .filter((f) => f.endsWith('.json'))
55	        .map((f) => path.join(this.dataDir, f));
56	
57	      if (this._files.length === 0) {
58	        this.logger.warn(`No .json files found in data directory: ${this.dataDir}`);
59	      }
60	
61	      return [...this._files];
62	    } catch (err) {
63	      this.logger.warn(`Failed to list files in ${this.dataDir}`, { error: String(err) });
64	      this._files = [];
65	      return [];
66	    }
67	  }
68	
69	  /**
70	   * Load all .json files from the configured directory and merge them into
71	   * a single flat array of RawNewsItem objects.
72	   *
73	   * Files that fail to parse are logged as WARN and skipped (they do not
74	   * interrupt the overall process).
75	   */
76	  async loadAll(): Promise<RawNewsItem[]> {
77	    const files = this.listFiles();
78	    if (files.length === 0) {
79	      return [];
80	    }
81	
82	    const allItems: RawNewsItem[] = [];
83	
84	    for (const filePath of files) {
85	      try {
86	        const items = await this.loadFile(filePath);
87	        allItems.push(...items);
88	      } catch (err) {
89	        this.logger.warn(`Skipping file ${filePath} due to error`, { error: String(err) });
90	      }
91	    }
92	
93	    this.logger.info(`Loaded ${allItems.length} raw items from ${files.length} file(s)`);
94	
95	    return allItems;
96	  }
97	
98	  /**
99	   * Load and parse a single JSON file, returning RawNewsItem[].
100	   *
101	   * If the file contains a single object (not an array), it is automatically
102	   * wrapped in an array for uniform return type.
103	   *
104	   * @throws If the file cannot be read or JSON.parse fails.
105	   */
106	  async loadFile(filePath: string): Promise<RawNewsItem[]> {
107	    const raw = fs.readFileSync(filePath, 'utf-8');
108	    const parsed: unknown = JSON.parse(raw);
109	
110	    if (Array.isArray(parsed)) {
111	      return parsed as RawNewsItem[];
112	    }
113	
114	    // Single object — wrap in array
115	    return [parsed as RawNewsItem];
116	  }
117	}
