function createPipelineMock(): LLMClient {
  const allItems = loadFixture('valid-news');

  // EXTRACT responses: one valid StructuredInsightItem per item
  const extractResponses: LLMResponse[] = allItems.map((item) =>
    makeLLMResponse(makeMockInsight({ id: item.id, title: item.title })),
  );

  // SYNTHESIZE responses
  const topEventsJson = makeTopEventsJSON();
  const deepAnalysisJson1 = makeDeepAnalysisJSON('AI Model Releases and Advancements');
  const deepAnalysisJson2 = makeDeepAnalysisJSON('AI Regulation and Safety Framework Updates');
  const deepAnalysisJson3 = makeDeepAnalysisJSON('Enterprise AI and Open Source Ecosystem Growth');
  const trendsJson = makeTrendsJSON();
  const riskOppJson = makeRiskOppJSON();

  const synthesizeResponses: LLMResponse[] = [
    makeLLMResponse(topEventsJson),
    makeLLMResponse(deepAnalysisJson1),
    makeLLMResponse(deepAnalysisJson2),
    makeLLMResponse(deepAnalysisJson3),
    makeLLMResponse(trendsJson),
    makeLLMResponse(riskOppJson),
  ];

  const allResponses = [...extractResponses, ...synthesizeResponses];
  let callIndex = 0;

  return {
    send: async () => {
      const resp = allResponses[Math.min(callIndex, allResponses.length - 1)];
      callIndex++;
      return resp;
    },
  } as unknown as LLMClient;
