220	    }
221	
222	    // ===================================================================
223	    // Phase 3: SYNTHESIZE
224	    // ===================================================================
225	    if (stageIdx <= 2) {
226	      this.logger.info('Starting SYNTHESIZE stage');
227	      try {
228	        // Phase A: Aggregate statistics
229	        this.logger.info('SYNTHESIZE Phase A: Aggregating statistics');
230	        const aggregator = new StatsAggregator();
231	        stats = aggregator.aggregate(extractedItems);
232	
233	        // Phase B: Identify top events
234	        this.logger.info('SYNTHESIZE Phase B: Identifying top events');
235	        const analyzer = new InsightAnalyzer({ llmClient: this.options.llmClient });
236	        const topEvents = await analyzer.identifyTopEvents({
237	          topicFrequency: stats.topic_frequency,
238	          topBySignificance: extractedItems.filter(
239	            (item) => stats.top_by_significance.some((t) => t.id === item.id),
240	          ),
241	        });
242	
243	        // Phase C: Deep analysis for each event
244	        this.logger.info(`SYNTHESIZE Phase C: Analyzing ${topEvents.length} event(s) in depth`);
245	        const deepAnalyses: import('../schema/types.js').DeepAnalysis[] = [];
246	        for (const event of topEvents) {
247	          const relatedItems = extractedItems.filter(
248	            (item) => event.item_ids.includes(item.id),
249	          );
250	          const deepAnalysis = await analyzer.analyzeEvent(event, relatedItems);
251	          deepAnalyses.push(deepAnalysis);
252	        }
253	
254	        // Phase D: Trend analysis
255	        this.logger.info('SYNTHESIZE Phase D: Analyzing trends');
256	        trends = await analyzer.analyzeTrends(extractedItems, topEvents);
257	
258	        // Phase E: Risk and opportunity identification
259	        this.logger.info('SYNTHESIZE Phase E: Identifying risks and opportunities');
260	        const riskOpp = await analyzer.identifyRisksAndOpportunities(extractedItems, trends);
261	
262	        // Phase F: Build report
263	        this.logger.info('SYNTHESIZE Phase F: Building report');
264	        const builder = new ReportBuilder();
265	        report = builder.buildReport(date, stats, topEvents, deepAnalyses, trends, riskOpp);
266	
267	        synthesizeStage.status = 'success';
268	        synthesizeStage.report = report;
269	        this.logger.info('SYNTHESIZE stage completed');
270	      } catch (err) {
271	        this.logger.error('SYNTHESIZE stage failed', { error: String(err) });
272	        synthesizeStage.status = 'failed';
273	        synthesizeStage.error = String(err);
274	      }
275	    }
276	
277	    // ===================================================================
278	    // Phase 4: VISUALIZE
279	    // ===================================================================
280	    if (stageIdx <= 3) {
281	      this.logger.info('Starting VISUALIZE stage');
282	      try {
283	        const charts = generateAllCharts(stats, trends, date);
284	        visualizeStage.status = 'success';
285	        visualizeStage.charts = charts;
286	        this.logger.info('VISUALIZE stage completed');
287	      } catch (err) {
288	        this.logger.error('VISUALIZE stage failed', { error: String(err) });
289	        visualizeStage.status = 'failed';
290	        visualizeStage.error = String(err);
291	        visualizeStage.charts = {
292	          topicBarChart: '',
293	          sentimentDonut: '',
294	          trendRadar: '',
295	          eventTimeline: '',
296	        };
297	      }
298	    }
299	
300	    // ===================================================================
301	    // Final result
302	    // ===================================================================
303	    const totalDurationMs = Date.now() - startTime;
304	    const allSkipped = STAGE_ORDER.slice(stageIdx).every(
305	      (s) => {
306	        switch (s) {
307	          case 'ingest': return ingestStage.status === 'skipped';
308	          case 'extract': return extractStage.status === 'skipped';
309	          case 'synthesize': return synthesizeStage.status === 'skipped';
310	          case 'visualize': return visualizeStage.status === 'skipped';
311	        }
312	        return false;
313	      },
314	    );
315	
316	    // Pipeline is successful if none of the required stages explicitly failed
317	    // and at least one stage actually ran
318	    const hasRunningStage = STAGE_ORDER.slice(stageIdx).some((s) => {
319	      switch (s) {
320	        case 'ingest': return ingestStage.status !== 'skipped';
321	        case 'extract': return extractStage.status !== 'skipped';
322	        case 'synthesize': return synthesizeStage.status !== 'skipped';
323	        case 'visualize': return visualizeStage.status !== 'skipped';
324	      }
325	      return false;
326	    });
327	
328	    // Determine success: all required stages must not be 'failed'
329	    const allRequiredSucceeded = STAGE_ORDER.slice(stageIdx).every((s) => {
330	      switch (s) {
331	        case 'ingest': return ingestStage.status !== 'failed';
332	        case 'extract': return extractStage.status !== 'failed';
333	        case 'synthesize': return synthesizeStage.status !== 'failed';
334	        case 'visualize': return visualizeStage.status !== 'failed';
335	      }
336	      return true;
337	    });
338	
339	    // EXTRACT failure is non-blocking (pipeline continues), so don't fail overall for it
340	    // Only INGEST and SYNTHESIZE failures make the overall pipeline fail
341	    const success = hasRunningStage && allRequiredSucceeded;
342	
343	    this.logger.info(
344	      `Pipeline finished in ${totalDurationMs}ms — success=${success}`,
345	    );
346	
347	    return {
348	      success,
349	      date,
350	      stages: {
351	        ingest: ingestStage,
352	        extract: extractStage,
353	        synthesize: synthesizeStage,
354	        visualize: visualizeStage,
355	      },
356	      totalDurationMs,
357	    };
358	  }
359	}
